create or replace function public.crm_capture_predictive_outcomes(p_model_version text default 'deterministic_behavioral_v1') returns integer language plpgsql security definer set search_path=public as $$ declare n integer:=0; begin if auth.role()<>'service_role' then raise exception 'service_role_required'; end if; with candidates as (select e.id,e.conversation_id from public.crm_predictive_evaluations e where e.model_version=p_model_version and e.actual_conversion is null), outcomes as (select c.id,exists(select 1 from public.sales s join public.crm_conversations cv on cv.id=c.conversation_id where s.user_id=cv.user_id and s.transaction_id::text=cv.transaction_id::text and coalesce(s.status,'') in ('paid','approved','completed','success')) as converted from candidates c) update public.crm_predictive_evaluations e set actual_conversion=o.converted,evaluated_at=now() from outcomes o where e.id=o.id; get diagnostics n=row_count; return n; end; $$; revoke all on function public.crm_capture_predictive_outcomes(text) from public,anon,authenticated; grant execute on function public.crm_capture_predictive_outcomes(text) to service_role;